mapper.select:
SELECT id, activity_name AS activityName, plan_id AS planId, apply_start_date AS applyStartDate, apply_end_date AS applyEndDate, activity_start_date AS activityStartDate, activity_end_date AS activityEndDate, price, recruit_num AS recruitNum, registered_num AS registeredNum, status, remark, create_time AS createTime, update_time AS updateTime, COALESCE(( SELECT COUNT(*) FROM user_collect uc WHERE uc.target_type = 'study_activity' AND uc.target_id = CAST(study_tour_activity.id AS CHAR) ), 0) AS collectNumber FROM study_tour_activity
AND activity_name LIKE CONCAT('%', #{activityName}, '%')
AND plan_id = #{planId}
AND status = #{status}
ORDER BY create_time DESC
